:root {
  color-scheme: dark;
  --bg: #0d1117;
  --bg-2: #101720;
  --panel: rgba(17, 25, 37, 0.78);
  --panel-2: rgba(22, 33, 48, 0.9);
  --line: rgba(148, 163, 184, 0.18);
  --line-strong: rgba(125, 249, 190, 0.34);
  --text: #f6f8fa;
  --muted: #9caabd;
  --soft: #c7d0df;
  --green: #7df9be;
  --cyan: #48d7ff;
  --blue: #6ea8ff;
  --violet: #a78bfa;
  --amber: #ffd166;
  --danger: #ff7b72;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
  --radius: 22px;
  --radius-sm: 14px;
  --nav-h: 72px;
  --max: 1180px;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--sans);
  color: var(--text);
  background:
    radial-gradient(circle at 14% 0%, rgba(72, 215, 255, 0.16), transparent 34rem),
    radial-gradient(circle at 82% 8%, rgba(125, 249, 190, 0.12), transparent 30rem),
    linear-gradient(180deg, #0d1117 0%, #0b1017 58%, #080c11 100%);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }
::selection { background: rgba(125, 249, 190, 0.25); color: var(--text); }

.skip-link {
  position: fixed;
  top: 10px;
  left: 10px;
  z-index: 100;
  background: var(--green);
  color: #06100c;
  padding: 10px 14px;
  border-radius: 999px;
  transform: translateY(-140%);
  transition: transform 180ms ease;
}
.skip-link:focus { transform: translateY(0); outline: 3px solid rgba(72, 215, 255, 0.55); }

.topbar {
  position: sticky;
  top: 0;
  z-index: 50;
  height: var(--nav-h);
  border-bottom: 1px solid var(--line);
  background: rgba(13, 17, 23, 0.78);
  backdrop-filter: blur(18px);
}
.nav {
  max-width: calc(var(--max) + 48px);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 22px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.logo {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  color: #07130f;
  background: linear-gradient(135deg, var(--green), var(--cyan));
  box-shadow: 0 0 28px rgba(125, 249, 190, 0.26);
  font-family: var(--mono);
  font-weight: 900;
}
.navlinks {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}
.navlinks a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  padding: 0 12px;
  color: var(--soft);
  border-radius: 999px;
  font-size: 14px;
  transition: color 160ms ease, background 160ms ease;
}
.navlinks a:hover, .navlinks a.active, .navlinks a:focus-visible {
  color: var(--text);
  background: rgba(255, 255, 255, 0.07);
  outline: none;
}
.utility { display: flex; align-items: center; gap: 10px; margin-left: 8px; }
.search-pill, .icon-btn {
  min-height: 44px;
  border: 1px solid var(--line);
  color: var(--soft);
  background: rgba(255, 255, 255, 0.035);
  border-radius: 999px;
}
.search-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  font-size: 14px;
}
.icon-btn { width: 44px; display: grid; place-items: center; }
.mobile-toggle { display: none; }

.container { max-width: var(--max); margin: 0 auto; padding: 0 24px; }
.hero {
  padding: 92px 0 56px;
  position: relative;
  overflow: hidden;
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(300px, 0.88fr);
  gap: 46px;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--green);
  background: rgba(125, 249, 190, 0.08);
  border: 1px solid rgba(125, 249, 190, 0.22);
  padding: 7px 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
}
h1, h2, h3 { line-height: 1.05; letter-spacing: -0.045em; margin: 0; }
h1 { font-size: clamp(44px, 7vw, 84px); margin-top: 18px; max-width: 900px; }
h2 { font-size: clamp(30px, 4vw, 52px); }
h3 { font-size: 22px; }
p { margin: 0; color: var(--muted); }
.lede { font-size: clamp(18px, 2vw, 21px); color: var(--soft); max-width: 760px; margin-top: 22px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.btn {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--text);
  background: rgba(255, 255, 255, 0.045);
  font-weight: 750;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}
.btn:hover, .btn:focus-visible { transform: translateY(-1px); border-color: rgba(125, 249, 190, 0.4); outline: none; }
.btn.primary { color: #03120d; background: linear-gradient(135deg, var(--green), var(--cyan)); border: 0; box-shadow: 0 16px 46px rgba(72, 215, 255, 0.16); }
.btn.subtle { color: var(--soft); }

.orb-card, .glass-card, .product-card, .code-panel, .section-panel, .resource-card {
  background: linear-gradient(180deg, rgba(22, 32, 46, 0.78), rgba(13, 20, 30, 0.82));
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}
.orb-card { border-radius: 30px; padding: 22px; position: relative; min-height: 390px; overflow: hidden; }
.orb-card::before {
  content: "";
  position: absolute;
  inset: -30% -20% auto auto;
  width: 340px;
  height: 340px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(125, 249, 190, 0.35), transparent 64%);
  filter: blur(8px);
}
.terminal-window { position: relative; z-index: 1; border-radius: 20px; overflow: hidden; border: 1px solid rgba(255,255,255,.12); background: #070b10; }
.terminal-top { display: flex; gap: 7px; padding: 14px; border-bottom: 1px solid rgba(255,255,255,.08); }
.dot { width: 11px; height: 11px; border-radius: 50%; background: var(--danger); }
.dot:nth-child(2) { background: var(--amber); }
.dot:nth-child(3) { background: var(--green); }
.terminal-body { padding: 20px; font-family: var(--mono); font-size: 13px; color: #d6e4f0; }
.terminal-body .prompt { color: var(--green); }
.terminal-body .comment { color: #7d8ca1; }
.stat-strip { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 16px; }
.stat { padding: 14px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,255,255,.04); }
.stat b { display: block; font-size: 20px; color: var(--text); }
.stat span { color: var(--muted); font-size: 12px; }

section { padding: 62px 0; }
.section-head { display: flex; justify-content: space-between; gap: 24px; align-items: end; margin-bottom: 24px; }
.section-head p { max-width: 680px; color: var(--soft); }
.grid { display: grid; gap: 18px; }
.grid.three { grid-template-columns: repeat(3, 1fr); }
.grid.two { grid-template-columns: repeat(2, 1fr); }
.grid.six { grid-template-columns: repeat(3, 1fr); }

.product-card, .resource-card, .glass-card, .section-panel {
  border-radius: var(--radius);
  padding: 24px;
  position: relative;
  overflow: hidden;
}
.product-card::before, .resource-card::before, .glass-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: linear-gradient(90deg, var(--accent, var(--green)), transparent);
}
.product-card { min-height: 280px; display: flex; flex-direction: column; }
.product-icon, .mini-icon {
  width: 48px;
  height: 48px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  color: #06100c;
  background: linear-gradient(135deg, var(--accent, var(--green)), rgba(255,255,255,.88));
  font-family: var(--mono);
  font-weight: 900;
}
.product-card p, .resource-card p, .glass-card p { margin-top: 12px; }
.card-link { margin-top: auto; padding-top: 22px; color: var(--accent, var(--green)); font-weight: 800; }
.card-list { list-style: none; padding: 0; margin: 18px 0 0; display: grid; gap: 10px; }
.card-list li { color: var(--soft); display: flex; gap: 9px; }
.card-list li::before { content: ""; width: 7px; height: 7px; margin-top: 9px; border-radius: 50%; background: var(--accent, var(--green)); flex: 0 0 auto; }

.cli-shell { display: grid; grid-template-columns: 0.9fr 1.1fr; gap: 18px; align-items: start; }
.accordion { display: grid; gap: 12px; }
.accordion-item { border: 1px solid var(--line); border-radius: 18px; background: rgba(255,255,255,.035); overflow: hidden; }
.accordion-button {
  width: 100%;
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 18px;
  background: transparent;
  color: var(--text);
  border: 0;
  text-align: left;
  font-weight: 800;
}
.accordion-button span { color: var(--green); transition: transform 180ms ease; }
.accordion-item.open .accordion-button span { transform: rotate(45deg); }
.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 240ms ease;
}
.accordion-item.open .accordion-content { max-height: 260px; }
.accordion-content ol { margin: 0; padding: 0 20px 20px 42px; color: var(--soft); }
.accordion-content li + li { margin-top: 9px; }
.code-panel { border-radius: var(--radius); overflow: hidden; }
.tabs { display: flex; gap: 6px; padding: 12px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,.025); }
.tab {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid transparent;
  color: var(--muted);
  background: transparent;
  font-weight: 800;
}
.tab.active, .tab:hover, .tab:focus-visible { color: #06100c; background: var(--green); outline: none; }
pre { margin: 0; overflow-x: auto; }
.code-body { padding: 22px; background: #070b10; }
.code-body code { font-family: var(--mono); color: #d6e4f0; font-size: 14px; }
.code-line { display: block; white-space: pre; }
.code-line .prompt { color: var(--green); }
.code-line .cmd { color: #f6f8fa; }
.code-line .muted { color: #8191a6; }

.launch-grid { grid-template-columns: repeat(2, 1fr); }
.community-grid { grid-template-columns: repeat(4, 1fr); }

.docs-layout {
  max-width: 1440px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 34px;
  padding: 26px 24px 0;
}
.sidebar {
  position: sticky;
  top: calc(var(--nav-h) + 22px);
  align-self: start;
  height: calc(100vh - var(--nav-h) - 44px);
  border: 1px solid var(--line);
  border-radius: 24px;
  background: rgba(13, 17, 23, 0.66);
  backdrop-filter: blur(18px);
  padding: 14px;
  transition: width 220ms ease, padding 220ms ease;
  overflow: hidden;
}
.sidebar-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px; }
.sidebar-title { font-weight: 850; letter-spacing: -0.02em; white-space: nowrap; }
.collapse-btn {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.04);
  color: var(--text);
}
.sidebar nav { display: grid; gap: 4px; margin-top: 12px; }
.sidebar nav a {
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 11px;
  border-radius: 13px;
  color: var(--soft);
  font-size: 14px;
}
.sidebar nav a:hover, .sidebar nav a.active, .sidebar nav a:focus-visible { background: rgba(125,249,190,.09); color: var(--text); outline: none; }
.nav-glyph { width: 22px; text-align: center; color: var(--green); font-family: var(--mono); flex: 0 0 22px; }
.docs-layout.sidebar-collapsed { grid-template-columns: 78px minmax(0, 1fr); }
.docs-layout.sidebar-collapsed .sidebar { padding: 10px; }
.docs-layout.sidebar-collapsed .sidebar-title, .docs-layout.sidebar-collapsed .link-text { opacity: 0; width: 0; overflow: hidden; white-space: nowrap; }
.docs-layout.sidebar-collapsed .sidebar nav a { justify-content: center; padding: 0; }
.docs-layout.sidebar-collapsed .sidebar-head { justify-content: center; padding: 4px 0; }
.docs-layout.sidebar-collapsed .collapse-btn { transform: rotate(180deg); }
.docs-main { min-width: 0; }
.docs-main .hero { padding-top: 50px; }
.docs-hero-card {
  border: 1px solid var(--line);
  border-radius: 30px;
  padding: clamp(28px, 5vw, 54px);
  background: radial-gradient(circle at 85% 10%, rgba(72, 215, 255, 0.16), transparent 32rem), linear-gradient(180deg, rgba(22,32,46,.72), rgba(13,20,30,.78));
  box-shadow: var(--shadow);
}
.docs-section { scroll-margin-top: 96px; padding: 46px 0; }
.docs-section h2 { margin-bottom: 14px; }
.card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 22px; }
.info-card {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: rgba(255,255,255,.035);
  padding: 20px;
  min-height: 158px;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
}
.info-card:hover { transform: translateY(-2px); border-color: rgba(125,249,190,.26); background: rgba(255,255,255,.052); }
.info-card h3 { font-size: 19px; letter-spacing: -0.03em; }
.info-card p { margin-top: 9px; font-size: 14.5px; }
.info-card .tag { display: inline-flex; margin-bottom: 14px; color: var(--green); font-family: var(--mono); font-size: 12px; }
.feature-list { margin: 20px 0 0; padding: 0; list-style: none; display: grid; gap: 12px; }
.feature-list li { border: 1px solid var(--line); border-radius: 16px; padding: 16px; background: rgba(255,255,255,.03); color: var(--soft); }
.feature-list strong { color: var(--text); }
.actor-flow { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 22px; }
.actor { text-align: center; padding: 22px 14px; border: 1px solid var(--line); border-radius: 20px; background: rgba(255,255,255,.035); }
.actor b { display: block; font-size: 22px; color: var(--green); font-family: var(--mono); text-transform: uppercase; }
.actor span { display: block; color: var(--muted); margin-top: 8px; font-size: 14px; }
.status-pill { display: inline-flex; color: #07100c; background: var(--amber); border-radius: 999px; padding: 5px 10px; font-weight: 850; font-size: 12px; margin-top: 16px; }

.support-hero { text-align: center; max-width: 820px; margin: 0 auto; }
.support-hero .lede { margin-left: auto; margin-right: auto; }
.support-cards { grid-template-columns: repeat(4, 1fr); }

.footer {
  border-top: 1px solid var(--line);
  margin-top: 64px;
  padding: 44px 0;
  background: rgba(0,0,0,.16);
}
.footer-grid { display: grid; grid-template-columns: 1.2fr repeat(4, 1fr); gap: 26px; }
.footer h4 { margin: 0 0 12px; color: var(--text); }
.footer a, .footer p { display: block; color: var(--muted); font-size: 14px; margin: 8px 0; }
.footer a:hover { color: var(--green); }

:focus-visible { outline: 3px solid rgba(72, 215, 255, 0.6); outline-offset: 2px; }

@media (max-width: 980px) {
  .mobile-toggle { display: grid; }
  .nav { gap: 12px; }
  .navlinks {
    position: fixed;
    top: var(--nav-h);
    left: 16px;
    right: 16px;
    display: none;
    flex-direction: column;
    align-items: stretch;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 22px;
    background: rgba(13, 17, 23, .96);
    box-shadow: var(--shadow);
  }
  .navlinks.open { display: flex; }
  .navlinks a { justify-content: center; }
  .search-pill { display: none; }
  .hero-grid, .cli-shell, .grid.three, .grid.two, .launch-grid, .community-grid, .support-cards { grid-template-columns: 1fr; }
  .grid.six, .card-grid { grid-template-columns: repeat(2, 1fr); }
  .docs-layout, .docs-layout.sidebar-collapsed { grid-template-columns: 1fr; padding-top: 16px; }
  .sidebar {
    position: relative;
    top: 0;
    height: auto;
  }
  .docs-layout.sidebar-collapsed .sidebar nav { display: none; }
  .docs-layout.sidebar-collapsed .sidebar-title { opacity: 1; width: auto; }
  .docs-layout.sidebar-collapsed .sidebar-head { justify-content: space-between; }
  .actor-flow { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  :root { --nav-h: 66px; }
  .container, .nav, .docs-layout { padding-left: 16px; padding-right: 16px; }
  .brand span { display: none; }
  .hero { padding: 58px 0 36px; }
  section { padding: 42px 0; }
  .hero-actions .btn { width: 100%; }
  .grid.six, .card-grid, .actor-flow, .stat-strip { grid-template-columns: 1fr; }
  .section-head { display: block; }
  .section-head p { margin-top: 12px; }
  .orb-card { min-height: auto; }
  .product-card { min-height: 230px; }
  .tabs { overflow-x: auto; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.001ms !important; animation-duration: 0.001ms !important; scroll-behavior: auto !important; }
}
